const fs = require('fs');
const path = require('path');

const dataDir = 'data';
const resultsDir = 'results';

// Input files (JSON generated by change-logs.js)
const bacomLastPublishedFile = path.join(dataDir, 'bacom-last-published-bulk.json');
const daLastPublishedFile = path.join(dataDir, 'da-bacom-last-published.json');
const daLastDeletedFile = path.join(dataDir, 'da-bacom-last-deleted.json');

// Output files
const txtOutputFileName = 'paths-to-reimport-to-da-bacom.txt';
const jsonOutputFileName = 'paths-to-reimport-to-da-bacom.json';
const supersededJsonOutputFileName = 'paths-to-not-reimport-to-da-bacom.json';
const txtOutputFilePath = path.join(resultsDir, txtOutputFileName);
const jsonOutputFilePath = path.join(resultsDir, jsonOutputFileName);
const supersededJsonOutputFilePath = path.join(resultsDir, supersededJsonOutputFileName);

/**
 * Reads a JSON file containing last action details and extracts paths, timestamps, and users into a Map.
 * @param {string} filePath Path to the JSON file.
 * @returns {Map<string, { timestamp: string, user: string | null }> | null} Map of path -> {timestamp, user}, or null on error.
 */
function readActionFileToMap(filePath) {
  console.log(`Reading action file: ${filePath}...`);
  let entries;
  try {
    const rawData = fs.readFileSync(filePath, 'utf8');
    entries = JSON.parse(rawData);
  } catch (err) {
    if (err.code === 'ENOENT') {
      // It's okay if a file doesn't exist, treat it as empty
      console.warn(`Warning: Input file not found - ${filePath}. Assuming empty.`);
      return new Map(); 
    } else if (err instanceof SyntaxError) {
      console.error(`Error: Failed to parse JSON from ${filePath}.`, err);
    } else {
      console.error(`Error reading file ${filePath}:`, err);
    }
    return null; // Indicate critical error
  }

  if (!Array.isArray(entries)) {
    console.error(`Error: Expected an array in ${filePath}, but got ${typeof entries}`);
    return null;
  }

  const pathsMap = new Map();
  for (const entry of entries) {
    if (entry && typeof entry.path === 'string' && typeof entry.timestamp === 'string') {
      const timestamp = entry.timestamp;
      const user = entry.user || null; // Extract user (already done in extract-last-actions)
      const path = entry.path;

      const existingData = pathsMap.get(path);
      // Keep the latest timestamp if duplicates exist 
      if (!existingData || timestamp > existingData.timestamp) {
         pathsMap.set(path, { timestamp: timestamp, user: user }); // Store object
      }
    } else {
        console.warn(`Skipping invalid entry in ${filePath}:`, entry);
    }
  }
  console.log(`Extracted ${pathsMap.size} path-timestamp-user pairs from ${filePath}.`);
  return pathsMap;
}

// --- Main Logic ---
const bacomPubMap = readActionFileToMap(bacomLastPublishedFile);
const daPubMap = readActionFileToMap(daLastPublishedFile);
const daDelMap = readActionFileToMap(daLastDeletedFile);

if (!bacomPubMap || !daPubMap || !daDelMap) {
  console.error("Aborting due to critical errors reading input files.");
  process.exit(1);
}

const newerBacomPaths = [];
const newerBacomDetails = [];
const supersededBacomDetails = [];

for (const [bacomPath, bacomData] of bacomPubMap.entries()) {
  const bacomTimestamp = bacomData.timestamp;
  const bacomUser = bacomData.user;

  const daPubData = daPubMap.get(bacomPath); // -> { timestamp, user } or undefined
  const daDelData = daDelMap.get(bacomPath); // -> { timestamp, user } or undefined

  const daPubTimestamp = daPubData?.timestamp; // Use optional chaining
  const daPubUser = daPubData?.user;
  const daDelTimestamp = daDelData?.timestamp;
  const daDelUser = daDelData?.user;

  let latestDaTimestamp = null;

  // Determine the latest timestamp recorded on DA (either publish or delete)
  if (daPubTimestamp && daDelTimestamp) {
    latestDaTimestamp = daPubTimestamp > daDelTimestamp ? daPubTimestamp : daDelTimestamp;
  } else if (daPubTimestamp) {
    latestDaTimestamp = daPubTimestamp;
  } else if (daDelTimestamp) {
    latestDaTimestamp = daDelTimestamp;
  }

  // Create the details object once
  const details = {
    path: "https://main--bacom--adobecom.aem.live" + bacomPath,
    "last publish bacom": bacomTimestamp,
    "user last publish bacom": bacomUser, // Add bacom user
    "last publish da": daPubTimestamp || null,
    "user last publish da": daPubUser || null, // Add DA publish user
    "last delete da": daDelTimestamp || null,
    "user last delete da": daDelUser || null // Add DA delete user
  };

  // accept that we'll be overriding some paths that were edited in Bacom

  // newerBacomPaths.push("https://main--bacom--adobecom.aem.live" + bacomPath);
  // newerBacomDetails.push(details);

  // uncomment this code if we don't want to override content
  // Include if no final action recorded on DA, OR 
  // if the Bacom publish timestamp is >= the latest recorded DA action timestamp.
  if (!latestDaTimestamp || bacomTimestamp >= latestDaTimestamp) {
    newerBacomPaths.push("https://main--bacom--adobecom.aem.live" + bacomPath);
    newerBacomDetails.push(details);
  } else {
    // Otherwise, the Bacom publish was superseded
    supersededBacomDetails.push(details); // Add to the superseded list
  }
}

console.log(`\nFound ${newerBacomPaths.length} paths where the last Bacom publish is not superseded by a later final action on DA Bacom.`);
console.log(`Found ${supersededBacomDetails.length} paths where the last Bacom publish WAS superseded by a later final action on DA Bacom.`);

